1: /**
2:  * Backend Media Access Gateway Handler (E04).
3:  *
4:  * Chức năng:
5:  * - Bảo vệ screenshot báo cáo không cho truy cập tự do qua URL vĩnh viễn.
6:  * - Xác thực phiên người dùng qua Bearer JWT header.
7:  * - Kiểm tra chữ ký số HMAC-SHA256 gắn với định danh user, report ID, variant và expiration.
8:  * - Kiểm tra quyền thời gian thực (author, owner, admin) và SLA 30 ngày qua Authority Adapter.
9:  * - Trực tiếp proxy/stream ảnh về client, TUYỆT ĐỐI KHÔNG redirect 302 lộ download token.
10:  */
11: 
12: import { createHmac } from 'node:crypto';
13: 
14: export const ALLOWED_VARIANTS = new Set(['full', 'thumb']);
15: 
16: export function createMediaGatewayHandler({
17:     authorityAdapter,
18:     storageAdapter,
19:     gatewaySecret,
20:     logger = console,
21: }) {
22:     if (!gatewaySecret || typeof gatewaySecret !== 'string') {
