1: #!/usr/bin/env node
2: 
3: /**
4:  * Worker dọn dẹp screenshot báo cáo quá hạn trên Google Cloud Storage (Firebase Storage).
5:  *
6:  * Chính sách lưu trữ:
7:  * - Screenshot báo cáo chỉ lưu tối đa 30 ngày tính theo metadata timeCreated (UTC).
8:  * - Bắt đầu dọn dẹp từ ngày thứ 29 (age >= 29 days) nhằm tạo biên an toàn 1 ngày
9:  *   cho retry mạng hoặc worker failure trước khi chạm hạn chót 30 ngày.
10:  * - Mọi object >= 30 ngày được xem là vi phạm SLA và phát cảnh báo khẩn cấp.
11:  * - Tuyệt đối không xóa hoặc quét prefix khác ngoài reports/ (ví dụ app_icons/ hay toàn bucket).
12:  * - Sử dụng ifGenerationMatch để chống race condition khi file bị ghi đè.
13:  * - 404 được xử lý idempotent thành công.
14:  * - Hỗ trợ --dry-run (hoặc DRY_RUN=true).
15:  */
16: 
17: // Storage client được nạp động nếu không truyền mock (giúp test chạy nhẹ nhàng không phụ thuộc external network)
18: let StorageClass = null;
19: async function getDefaultStorage() {
20:     if (!StorageClass) {
21:         const mod = await import('@google-cloud/storage');
22:         StorageClass = mod.Storage;
23:     }
24:     return new StorageClass();
25: }
26: 
27: export const ALLOWED_BUCKET = 'cross-testers.firebasestorage.app';
28: export const TARGET_PREFIX = 'reports/';
29: export const DEFAULT_TARGET_AGE_DAYS = 29;
30: export const DEFAULT_SLA_THRESHOLD_DAYS = 30;
31: 
32: /**
33:  * Thực hiện delay bất đồng bộ cho exponential backoff.
34:  */
35: function sleep(ms) {
36:     return new Promise(resolve => setTimeout(resolve, ms));
37: }
38: 
39: /**
40:  * Xóa file an toàn kèm retry cho lỗi mạng tạm thời (429, 5xx).
41:  */
42: async function deleteWithRetry(file, generation, maxRetries = 3) {
43:     let attempt = 0;
44:     while (attempt < maxRetries) {
45:         attempt++;
46:         try {
47:             await file.delete({ ifGenerationMatch: generation });
48:             return { status: 'DELETED' };
49:         } catch (err) {
50:             const statusCode = err?.code || err?.status || (err?.response && err.response.status);
51:             // 404: Idempotent - file đã bị xóa bởi process khác hoặc GCS Lifecycle
52:             if (statusCode === 404) {
53:                 return { status: 'ALREADY_DELETED' };
54:             }
55:             // 412: Precondition Failed - generation đã thay đổi (object bị ghi đè)
56:             if (statusCode === 412) {
57:                 return { status: 'PRECONDITION_FAILED', error: err.message };
58:             }
59:             // 429 hoặc 5xx: Retry với exponential backoff
60:             if ((statusCode === 429 || (statusCode >= 500 && statusCode < 600)) && attempt < maxRetries) {
61:                 const backoffMs = Math.pow(2, attempt) * 200 + Math.random() * 100;
62:                 await sleep(backoffMs);
63:                 continue;
64:             }
65:             throw err;
66:         }
67:     }
68: }
