            if ((statusCode === 429 || (statusCode >= 500 && statusCode < 600)) && attempt < maxRetries) {
                const backoffMs = Math.pow(2, attempt) * 200 + Math.random() * 100;
                await sleep(backoffMs);
                continue;
            }
            throw err;
        }
    }
