    sealed interface SubmitEvent {
        data class Success(
            val campaignId: String,
            val appName: String,
            val provisionalAmount: Int,
            val isMissionReport: Boolean = false,
            val missionTitle: String? = null,
        ) : SubmitEvent

        data class Failed(
