1: package com.ntt.crosstest.data
2: 
3: import android.app.Application
4: import org.junit.*
5: import org.junit.Assert.*
6: import org.junit.runner.RunWith
7: import org.robolectric.RobolectricTestRunner
8: import org.robolectric.RuntimeEnvironment
9: import org.robolectric.annotation.Config
10: import java.io.File
11: import java.io.IOException
12: 
13: @RunWith(RobolectricTestRunner::class)
14: @Config(application = Application::class, sdk = [34])
15: class PendingReportStoreTest {
16:     private val context: Application get() = RuntimeEnvironment.getApplication()
17:     @Before fun reset() { PendingReportStore.clear(context) }
18:     @After fun cleanup() { PendingReportStore.clear(context) }
19:     private fun report() = PendingReport("id", "campaign", "app", "user", 5, "feedback")
20:     @Test fun legacyJsonRemainsReadable() {
21:         File(PendingReportStore.directory(context), "id.json").writeText(
22:             """{"id":"id","campaignId":"campaign","appName":"app","userId":"user","rating":5,"comment":"feedback"}"""
23:         )
24:         val restored = PendingReportStore.read(context, "id")!!
25:         assertNull(restored.completedResult)
26:         assertNull(restored.screenshotSha256)
27:     }
28:     @Test fun completedReceiptSurvivesReReadAndCleanupWithoutBlockingSuggestions() {
29:         val image = PendingReportStore.newScreenshotFile(context, "id").apply { writeText("bytes") }
30:         PendingReportStore.write(context, report().copy(screenshotPath = image.path, createdAt = 0))
31:         val result = SubmitTesterReportResult(success = true, reportId = "server-id", provisionalGranted = true, provisionalAmount = 10)
32:         PendingReportStore.markCompleted(context, "id", result)
33:         assertNotNull("receipt JSON: " + File(PendingReportStore.directory(context), "id.json").readText(),
34:             PendingReportStore.read(context, "id"))
35:         PendingReportStore.cleanup(context)
36:         assertEquals(result, PendingReportStore.read(context, "id")!!.completedResult)
37:         assertFalse(image.exists())
38:         assertTrue(PendingReportStore.pendingCampaignIds(context).isEmpty())
39:     }
40:     @Test fun interruptedAtomicUpdatePreservesPreviousRequest() {
41:         PendingReportStore.write(context, report())
42:         File(PendingReportStore.directory(context), "id.json.tmp").writeText("incomplete JSON")
43:         assertEquals(report().comment, PendingReportStore.read(context, "id")!!.comment)
44:     }
45:     @Test fun legacyBackupIsRecoveredBeforeReading() {
46:         PendingReportStore.write(context, report())
47:         val base = File(PendingReportStore.directory(context), "id.json")
48:         base.copyTo(File(base.path + ".bak"))
49:         base.writeText("interrupted old write")
50:         assertEquals("feedback", PendingReportStore.read(context, "id")!!.comment)
51:     }
52:     @Test(expected = IOException::class) fun missingRecordCannotPretendToPersistUploadedUrl() {
53:         PendingReportStore.markUploaded(context, "missing", "url", "hash")
