                    missionId = missionId,
                    repository = app.campaignRepository,
                    reportSubmitManager = app.reportSubmitManager,
                    appContext = app,
                )
            }
        }
    )
    val uiState by actualViewModel.uiState.collectAsState()
    val snackbarHostState = remember { SnackbarHostState() }

