     fun put(
         context: Context,
         accountId: String,
         generation: Long,
         variant: ScreenshotVariant,
         url: String,
         bitmapBytes: ByteArray,
         cacheControlHeader: String?,
         reportCreatedAt: String?,
         mediaExpired: Boolean?,
         serverDateHeaderEpochMs: Long? = null,
         ageHeader: String? = null,
         isSessionValid: (() -> Boolean)? = null,
     ): Boolean {
