                 raf.writeInt(MAGIC_HEADER)
                 raf.writeLong(finalExpiryMs)
                 raf.writeLong(nowMs) // cachedAt
                 raf.writeInt(bitmapBytes.size)
                 raf.write(bitmapBytes)
             }
